`timescale 1ns/1ps
module multipath_memory_fabric #(parameter int REQUESTERS=8, PATHS=4, BANKS=8, ADDR_WIDTH=16, DATA_WIDTH=64, QOS_WIDTH=3)(input logic clk,rst_n,enable,input logic [REQUESTERS-1:0] req_valid,req_write,input logic [REQUESTERS-1:0][ADDR_WIDTH-1:0] req_addr,input logic [REQUESTERS-1:0][DATA_WIDTH-1:0] req_wdata,input logic [REQUESTERS-1:0][DATA_WIDTH/8-1:0] req_be,input logic [REQUESTERS-1:0][QOS_WIDTH-1:0] req_qos,output logic [REQUESTERS-1:0] req_grant,output logic [REQUESTERS-1:0][$clog2(PATHS)-1:0] req_grant_path,output logic [REQUESTERS-1:0][$clog2(BANKS)-1:0] req_grant_bank,output logic [PATHS-1:0] path_valid,path_write,output logic [PATHS-1:0][$clog2(BANKS)-1:0] path_bank,output logic [PATHS-1:0][ADDR_WIDTH-1:0] path_addr,output logic [PATHS-1:0][DATA_WIDTH-1:0] path_wdata,output logic [PATHS-1:0][DATA_WIDTH/8-1:0] path_be,output logic [PATHS-1:0][QOS_WIDTH-1:0] path_qos,output logic busy,output logic [$clog2(PATHS+1)-1:0] active_paths);
localparam int PW=(PATHS<=1)?1:$clog2(PATHS); localparam int BW=(BANKS<=1)?1:$clog2(BANKS); integer p,r; logic [BANKS-1:0] used_bank; logic [REQUESTERS-1:0] used_req; always_comb begin req_grant='0; req_grant_path='0; req_grant_bank='0; path_valid='0; path_write='0; path_bank='0; path_addr='0; path_wdata='0; path_be='0; path_qos='0; used_bank='0; used_req='0; active_paths='0; if(enable&&rst_n) begin for(p=0;p<PATHS;p=p+1) begin for(r=0;r<REQUESTERS;r=r+1) begin if(!path_valid[p]&&!used_req[r]&&req_valid[r]&&!used_bank[req_addr[r][BW-1:0]]) begin path_valid[p]=1'b1; path_write[p]=req_write[r]; path_bank[p]=req_addr[r][BW-1:0]; path_addr[p]=req_addr[r]; path_wdata[p]=req_wdata[r]; path_be[p]=req_be[r]; path_qos[p]=req_qos[r]; req_grant[r]=1'b1; req_grant_path[r]=p[PW-1:0]; req_grant_bank[r]=req_addr[r][BW-1:0]; used_bank[req_addr[r][BW-1:0]]=1'b1; used_req[r]=1'b1; active_paths=active_paths+1'b1; end end end end end assign busy=(active_paths!=0); endmodule
